                            for (seconds, nanos) in [(m.atime(), m.atime_nsec()), (m.mtime(), m.mtime_nsec()), (m.ctime(), m.ctime_nsec())] { row.push(Value::of_big(BigInt::from(seconds) * BigInt::from(1_000_000_000) + BigInt::from(nanos))); }
